        ("Besaran fisika yang satuannya diturunkan dari kombinasi besaran pokok dinamakan besaran ...", "Turunan", ["Pokok", "Vektor", "Skalar"]),
        ("Contoh kelompok besaran yang seluruhnya tergolong besaran pokok adalah ...", "Panjang, massa, dan waktu", ["Kecepatan, gaya, dan percepatan", "Luas, volume, dan massa jenis", "Usaha, daya, dan energi"]),
        ("Contoh kelompok besaran yang seluruhnya tergolong besaran turunan adalah ...", "Luas, kecepatan, dan gaya", ["Massa, panjang, dan waktu", "Suhu, kuat arus, dan intensitas cahaya", "Waktu, gaya, dan massa"]),
        ("Satuan internasional (SI) standar untuk besaran luas adalah ...", "Meter persegi (m2)", ["Meter kubik", "Hektare", "Sentimeter persegi"]),
        ("Satuan internasional (SI) standar untuk besaran volume adalah ...", "Meter kubik (m3)", ["Liter", "Meter persegi", "Mililiter"]),
        ("Satuan internasional (SI) standar untuk besaran kecepatan atau kelajuan adalah ...", "Meter per sekon (m/s)", ["Kilometer per jam", "Meter per sekon kuadrat", "Centimeter per sekon"]),
        ("Satuan internasional (SI) standar untuk besaran percepatan adalah ...", "Meter per sekon kuadrat (m/s2)", ["Meter per sekon", "Kilometer per jam", "Joule"]),
        ("Satuan internasional (SI) standar untuk besaran massa jenis (kerapatan zat) adalah ...", "kg/m3", ["g/cm3", "kg/liter", "m3/kg"]),
        ("Satuan internasional (SI) untuk besaran gaya dan berat adalah ...", "Newton (N)", ["Joule", "Pascal", "Watt"]),
        ("Satu Newton setara dengan gaya yang menghasilkan percepatan 1 m/s2 pada massa 1 kg, yaitu ...", "1 kg.m/s2", ["1 kg.m2/s2", "1 kg/m.s", "1 kg.s/m"]),
        ("Satuan internasional (SI) untuk besaran usaha dan energi adalah ...", "Joule (J)", ["Watt", "Newton", "Pascal"]),
        ("Satu Joule setara dengan usaha yang dilakukan gaya 1 Newton sejauh 1 meter, yaitu ...", "1 N.m (Newton meter)", ["1 N/m", "1 N.s", "1 N/s"]),
